internal object DuaKokDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_breaking_fast" to DuaText("उपवास मोडल्या उपरांत", "तान गेली, शिरां ओलयतात, आनी अल्लाह जाय जाल्यार इनाम निश्चीत जाता.", "इफ्ताराच्या वेळार.", "पैगंबर सल्लल्लाह अलीह वस्लमान आपलो उपवास मोडतना हें सांगलें."),
        "dua_new_clothes" to DuaText("नवे कपडे घालप", "हे अल्लाह, सगळ्यो तोखणाय तुमच्योच आसात; तूं म्हाका हें कपडे घातलां. हांव तुका ताचे बरे आनी ज्या खातीर तयार केल्ले ताचे बरे मागता, आनी हांव तुका ताचे वायट आनी वायट हांचे पसून आलाशिरो मागता.", "नवो भेस घालतना (ताका शर्ट वा पगडी अशें नांव दिवप).", "पैगंबर सल्लल्लाह अल्लीह वस्लमान नवो भेस घालतना ही दुआ केली. (कपडे घालपा खातीर दिसपट्टो दुआ'कपडे घालप \"ह्या खाला आसता.)"),
        "dua_rabbana_atina" to DuaText("ह्या संवसारांत आनी उपरांत बरें", "म्हज्या देवा, आमकां ह्या संवसारांत बरें आनी आख़िरतांत बरें दिवचें, आनी उज्याच्या ख्यास्तेकडल्यान आमची राखण करची.", "पैगंबर सल्ल्याह अलियाह मुसलमानान चड करून दुआ केली.", "एक दुआ जी ह्या संवसारांतली आनी आख़िरतांतली सगळीं बरी गजाली एकठांय करता."),
        "dua_rabbi_zidni_ilma" to DuaText("गिन्यान वाडप", "म्हज्या देवा, म्हाका गिन्यान वाडय.", "गिन्यान वाडोवपा खातीर.", "अल्लाहान पैगंबर सल्ल्युल्लाह अल्लीह वसलमाक गिन्यान सोडून हेर कांयच वाडोवंक मागचो न्हय असो आदेश दिलो."),
        "dua_musa_sharh_sadr" to DuaText("हड्डें उगडप (मुसा ए. एस.)", "म्हज्या देवा, म्हजे खातीर म्हजी हड्डें वाडय, म्हजें काम सोंपें कर, आनी म्हज्या जीबींतल्यान गांठी उगड, जाका लागून तांकां म्हजें उलोवप समजूंक शकतलें.", "परिक्षे पयलीं, भाशण वा खंयचेंय कठीण काम.", "पैगंबर मुसा (अ. स.) हाचें दुआ-काळजाची शांतताय आनी आपल्या कामांत सुसेग."),
        "dua_la_tuzigh" to DuaText("काळजाची स्थीरताय", "म्हज्या प्रभू, तूं आम्हांक मार्ग दाखयल्या उपरांत आमचीं काळजां विचलीत जावंक दिवं नाकात, आनी तुजीच दया कर. तूंच खरो दाता.", "मार्गदर्शनाचेर स्थैर्या खातीर.", "श्रद्धेचेर ठाम रावपा खातीर दुआ."),
        "dua_ya_muqallib" to DuaText("हे टर्नर ऑफ हार्ट्स", "हे काळजाचे टर्नर, म्हजें काळज तुज्या धर्माचेर तिगोवन दवर.", "पैगंबर सल्ल्याह अलियाह वसलमान चड करून ही दुआ केली.", "उम्म सलामाह (आर. ए.) हाच्या मतान पैगंबर सल्ल्याह अलियाह वस्लमान चड करून दुआ केली."),
        "dua_la_tuakhidhna" to DuaText("सूरह अल-बकाराहचे निमाणें श्लोक", "म्हज्या प्रभू, आमी विसरल्यार वा चुकल्यार आमचेर आरोप करचो न्हय. म्हज्या प्रभू, तूं आमचेर आमचे आदीं आशिल्ल्या लोकांचेर दवरिल्लो भार आमचेर घालचो न्हय. म्हज्या प्रभू, आमी सोंसूंक शकनाशिल्ले भार आमचेर घालचो न्हय. आम्हांक माफ कर, आम्हांक माफ कर आनी आमचेर दया कर. तूं आमचो राखणदार, देखून अविश्वास करपी लोकां आड आमची मदत कर.", "न्हिदचे पयलीं रातचें-सूरह अल-बकाराहचे निमाणें दोन श्लोक.", "जो कोण रातच्या वेळार सूरह अल-बकाराहचे निमाणें दोन श्लोक वाचता, ते ताका फावो जातले."),
        "dua_visiting_sick" to DuaText("दुयेंतीक भेट दिवप", "हांव म्हाल अल्लाहाक, म्हाल सिंहासनाचो स्वामी, तुका बरे करची अशी विनवणी करता.", "सात फावटीं दुयेंतीक भेट दितना.", "मरणाची वेळ ना आयल्यार अल्लाह ताका बरे करतलो."),
        "dua_ruqyah_pain" to DuaText("शारिरीक दुखणे खातीर", "म्हाका कितें दिसता आनी कितें भियेता ह्या वायट गजालीं पसून हांव अल्लाह आनी ताच्या सामर्थ्याचो आलाशिरो मागता.", "दुखता थंय हात दवरात, तीन फावट बिस्मिल्लाह म्हणात, मागीर सात फावटीं ही दुआ.", "पैगंबर सल्ल्याह अलियाह वसलमान उथमान इब्न अबील -'आस (रा.) हाका दुखपा खातीर तें शिकयलें."),
        "dua_ruqyah_nabawi" to DuaText("दुयेंतीं खातीर पयशाणीक रुक्या", "हे अल्लाह, मनशाच्या स्वामी! लुकसाण पयस कर आनी उपचार कर, कारण तूंच बरे करपी; तुज्या उपचाराखाला उपचार ना-एक उपचार जो खंयचेंच दुयेंस फाटीं सोडना.", "दुयेंत मनशाचेर हात घालतना.", "पैगंबर सल्लल्लाह अलीह वस्लमान आपल्या कुटुंबांतल्या दुयेंत वांगड्यांक भेट दितना हें पठण केलें."),
        "dua_kalimat_tammat" to DuaText("परिपूर्ण उतरांनी आश्रय सोदप", "ताणें निर्माण केल्ल्या वायट गजालीं पसून हांव अल्लाहच्या परिपूर्ण उतरांचो आलाशिरो मागता.", "खंयच्याय सुवातेर वा सांजवेळार थांबतना.", "जो कोणूय एका सुवातेर थांबून अशें म्हणटलो, तो तो सोडचे मेरेन ताका कांयच लुकसाण जायना."),
        "dua_evil_eye" to DuaText("भुरग्यांखातीर संरक्षण (वायट दोळे)", "हांव तुमच्या दोगांय खातीर, अल्लाहच्या परिपूर्ण उतरांनी, दरेक सैताना कडल्यान आनी दरेक विखारी प्राणी कडल्यान, आनी दरेक लुकसाण करपी दोळ्यां कडल्यान राखण मागता.", "पैगंबर सल्लल्लाह अलीह वस्लमान हसन आनी हुसेन (र.) हांचेचेर हें पठिल्लें.", "भुरग्यांक वायट दोळे आनी लुकसाण हांचे पसून वाटावपा खातीर सुन्नत दुआ (एका भुरग्याक'उधुका \"अशें म्हणटात)."),
        "dua_seeing_afflicted" to DuaText("कोणाकूय खटल्या भितर पळोवप", "सगळ्यो तोखणाय अल्लाहाक आसा, जाणें तुज्या परीक्षे पसून म्हाका मेकळीक दिली, आनी आपल्या सृष्टीचेर चडशें म्हाका उपकार केलो.", "कोणाकूय खटल्यांत पळयतकच (शांतपणान स्वता सांगात).", "जो म्हणटा तो त्या खटल्या पसून सुरक्षीत आसा."),
        "dua_istikhara" to DuaText("सलात अल-इस्तिकारा", "हे अल्लाह, हांव तुज्या गिन्यानांतल्यान बरें सोदता, हांव तुज्या शक्तींतल्यान क्षमता सोदता, आनी हांव तुज्या व्हड कृपे विशीं मागता. तुजे कडेन सत्ता आसा आनी म्हजे कडेन कोणूच ना; तूं जाणता आनी हांव ना, आनी तूं नदरें जाणा. हे अल्लाह, तुज्या गिन्यानांत जर ही गजाल (मतींत हाड) म्हज्या धर्मा खातीर, म्हज्या जिणे खातीर आनी म्हज्या शेवटाक बरी आसल्यार, म्हजे खातीर तो आदेश कर, म्हजे खातीर सोंपो कर आनी म्हाका तातूंत आशीर्वाद दे. आनी तुज्या गिन्यानांत जर ही गजाल म्हज्या धर्मा खातीर, म्हज्या जिणे खातीर आनी म्हज्या शेवटाक वायट आसल्यार, तें म्हजे कडल्यान पयस कर आनी म्हाका ताचे पसून पयस कर, आनी म्हजे खातीर जें बरें आसूं येता तें आदेश कर, मागीर म्हाका तातूंत समाधान कर.", "स्वेच्छेच्या प्रार्थनेच्या दोन रक्कथां उपरांत, परवानगी आशिल्ल्या बाबतींत सगळ्यांत बरें कितें तें सोदप.", "पैगंबर सल्लल्लाह अलीह वसलमान साथीदारांक कुराणाची सूरह शिकयतकच सगळ्या बाबतींत इस्तिकारा शिकयलो."),
        "dua_allahumma_bika_asbahna" to DuaText("अल्लाहुम्मा बीका अस्बाहना", "हे अल्लाह, आमी सकाळीं भितर सरतात आनी सांजीं भितर सरतात; आमी तिच्यावेळेन जगतात आनी तिच्यावेळेन मरण पावतात, आनी तुजे खातीर पुनरुत्थान आसा.", "सकाळीं.", "पैगंबर सल्ल्याह अलियाह वसलमान आज सकाळीं आनी सांजीं साथीदारांक सांगपाक शिकयलें."),
        "dua_allahumma_bika_amsayna" to DuaText("अल्लाहुम्मा बीका अम्सेना", "हे अल्लाह, आमी सांजवेळार तुमच्या वरवीं प्रवेश करतात आनी सकाळीं तुमच्या वरवीं प्रवेश करतात; आमी तुमच्या वरवीं जगतात आनी तुमच्या वरवीं मरतात, आनी तुजे कडेन परत येवप आसा.", "सांजवेळार.", "पैगंबर सल्ल्याह अलियाह वसलमान आज सकाळीं आनी सांजीं साथीदारांक सांगपाक शिकयलें."),
        "dua_afiyah_morning" to DuaText("अफिया मागप", "हे अल्लाह, हांव तुका ह्या संवसारांत आनी आख़िरतांत क्षमा आनी कल्याण मागता.", "पैगंबर सल्ल्याह अलियाह वसलमान सकाळीं वा सांजीं हे दुआक केन्नाच सोडूंक ना.", "कल्याणाकडल्यान बरें कोणाकूच कांय मेळ्ळें ना."),
        "dua_afini_fi_badani" to DuaText("कुडीची भलायकी, आयकुपाक आनी पळोवपाक", "हे अल्लाह, म्हज्या कुडीक कल्याण कर. हे अल्लाह, म्हज्या आयकुपाक कल्याण कर. हे अल्लाह, म्हज्या दोळ्यांक कल्याण कर. तूं सोडून देव ना.", "सकाळीं आनी सांजीं तीन फावटीं.", "भलायके खातीर आनी इंद्रियांची राखण करपा खातीर एक दुआ."),
        "dua_ya_hayyu_aslih" to DuaText("म्हज्या सगळ्या बाबतींत दुरुस्ती कर", "हे सदासर्वकाळ जगपी, हे पालनकर्ता, तुज्या दयेन हांव मदत मागताः म्हजें सगळे काम सारकें कर आनी म्हाका दोळे मिटपा खातीर लेगीत म्हजेचेर सोडचो न्हय.", "पैगंबर सल्ल्याह अलियाह वस्लमान फातिमाक (र.) सकाळ सांज म्हणपाचो सल्लो दिलो.", "दरेक बाबतींत अल्लाहाक मदत मागप."),
        "dua_subhanallah_adada_khalqihi" to DuaText("जुवरियाचो तसबीह (आर. ए.)", "अल्लाहाक गौरव आनी सगळी तोखणाय ताचीच-जितली ताची निर्मिती, जितली ताका आवडटा तितली, ताच्या सिंहासनाच्या वजनाइतली आनी ताच्या उतरांच्या शाईइतली.", "सकाळीं तीन फावटीं-धिकराच्या वरां परस चड वजन.", "हें चार वाक्यांश तीन फावटीं म्हणप सकाळीं सावन मध्य सकाळ मेरेन धिक्र परस चड म्हत्वाचें."),
        "dua_salawat" to DuaText("दुरूद-ए-इब्राहिम", "हे अल्लाह, मुहंमद सल्ल्याह अलीह वसीम आनी मुहंमदच्या घराण्याचेर प्रार्थना कर, जशें तूं इब्राहिम आनी इब्राहिमच्या घराण्याचेर प्रार्थना धाडटा; तूं स्तुत्य, गौरवशाली आसा. हे अल्लाह, मुहंमद सल्ल्याह अलीह वसीम आनी मुहंमदच्या कुटुंबाक आशीर्वाद दिवचो, जशें तूं इब्राहिम (अ. स.) आनी इब्राहिमच्या कुटुंबाक आशीर्वाद दिता; तूं तोखणाय, गौरवपूर्ण आसा.", "पैगंबर सल्ल्याह अलियाह ओस्लमाचेर प्रार्थनेंत आनी सदांच सलावत.", "जो एक फावट सलावत धाडटा, तो अल्लाह ताचेचेर धा दया दाखयता (मुसलमान 408)."),
        "dua_wudu_after" to DuaText("वुडू उपरांत", "एकलो, भागीदार नासतना, अल्लाह सोडून कोणाच्याकूय पुजा करपाचो अधिकार ना आनी मुहंमद सल्लल्लाह इस्लाम ताचो सेवक आनी संदेशवाहक आसा हाची हांव साक्षी दिता. हे अल्लाह, म्हाका पश्चात्ताप करपी आनी स्वताक शुद्ध करपी लोकां मदीं कर.", "वूडू पुराय केल्या उपरांत.", "स्वर्गांत वचपाक जाय आशिल्लीं आठ दारां ताका उक्तीं करतात."),
        "dua_wudu_before" to DuaText("वुडू पयलीं", "अल्लाहच्या नांवान.", "जेन्ना वूडू सुरू जाता.", "ताचेचेर अल्लाहचें नांव घेवंक नाशिल्ल्या मनशाक (पुराय) वुडू ना."),
        "dua_istiftah" to DuaText("उक्ती प्रार्थना (सना)", "हे अल्लाह, तुका गौरव आनी तोखणाय. तुजें नांव धन्य, तुजी भव्यताय उंचायेर, आनी तुज्या शिवाय देव ना.", "प्रार्थनेचे सुरवेक, उक्तावपी तकबीर जाले उपरांत.", "प्रार्थनेचो सुन्नत उक्तावपी दुआ."),
        "dua_ruku" to DuaText("रुकूंत", "म्हज्या प्रभूचो, भव्य देवाचो गौरव असो.", "उण्यांत उणें तीन फावटीं रुकू.", "रुकूचो सुन्नह तासबीह."),
        "dua_sujood" to DuaText("सुजूदांत", "म्हज्या परमप्रधान प्रभूचो गौरव असो.", "सुजूदांत उण्यांत उणें तीन फावटीं.", "सजदा करतना सेवक आपल्या प्रभूच्या सगळ्यांत लागीं आसता (मुसलमान 482)."),
        "dua_rising_ruku" to DuaText("रुकू सावन उगम पावप", "जो ताची तोखणाय करता तो अल्लाह आयकून घेता. म्हज्या प्रभू, सगळ्यो तोखणाय तुज्यापुर्याच आसात.", "रुकू सावन वयर सरतना आनी सरळ उबे रावतना.", "ज्याचें'रब्बाना वा लकल-हमद \"देवदूतांच्या पापांक मेळटा, ताचे फाटल्या पापांक माफ करतात."),
        "dua_between_sajdas" to DuaText("दोन सजदासां मदीं", "म्हज्या प्रभू, म्हाका माफ कर. म्हज्या प्रभू, म्हाका माफ कर.", "दोनूय साष्टांगां मदीं बसून.", "साष्टांग नमस्कारां मदीं बसपाचो सुन्नत दुआ."),
        "dua_before_salam_four" to DuaText("चार गजालींतल्यान शरण (सलाम पयलीं)", "हे अल्लाह, हांव नर्काची ख्यास्त, कबरीची ख्यास्त, जिवीत आनी मरणाच्या खटल्या, आनी खोट्या मसीहाच्या (दज्जल) खटल्याच्या वायट खिण्यां पसून तुका आलाशिरो मागता.", "निमाण्या ताशाहहुदा उपरांत आनी सलावा उपरांत, सलामा पयलीं.", "पैगंबर सल्ल्याह अलियाह वसलमान ह्या चार गजालीं पसून आलाशिरो घेवपाचो आदेश दिलो."),
        "dua_qunoot_witr" to DuaText("विटरांत कुनूट", "हे अल्लाह, तूं मार्गदर्शन करपी लोकां मदीं म्हाका मार्गदर्शन कर, तूं कल्याण दिवपी लोकां मदीं म्हाका कल्याण दिवचो, तूं तुज्या देखरेखी खाला हाडिल्ल्या लोकां मदीं म्हाका तुज्या देखरेखी खाला हाड, तुजे जे दिले तातूंत म्हाका आशीर्वाद दिवचो, आनी तूं जो आदेश दिता ताचे वायटपणांतल्यान म्हाका वाटावचो. तूं आदेश दिता आनी तुजे आड कोणूच आदेश दिना, आनी जाची इश्टागत करता ताचो केन्नाच अपमान जायना. धन्य आनी उदात्त तूं, हो आमचो प्रभू.", "विदर प्रार्थनेंत-पैगंबर सल्ल्याह अलियाह वसलमान हसन इब्न अली (रा.) हाका तें शिकयलें.", "विथरचें सुन्नत कुनूट. (हनाफीं मदीं'अल्लाहुम्मा इन्ना नास्तानुका'हेंय नामनेचें आसा.)"),
        "dua_qunoot_hanafi" to DuaText("कुनूत (अल्लाहुम्मा इन्ना नास्तानुका)", "हे अल्लाह, आमी तुजी मदत आनी तुझी क्षमा मागतात, आमी तुज्याचेर विस्वास दवरतात आनी तुजेचेर भरवंसा दवरतात, आमी तुजी तोखणाय करतात, आमी तुजी उपकार मानतात आनी कृतघ्न नात, आनी जो तुजी आज्ञा पाळो दिता ताका सोडून दितात. हे अल्लाह, आमी एकटे तुजेची पुजा करतात आनी नमस्कारा, तुजे कडेन आमी प्रार्थना करतात आनी सजदा करतात, तुजे वटेन आमी बेगोबेग यत्न करतात, तुज्या दयेची आशा दवरतात आनी तुज्या शिक्षेक भियेवतात; तुजी ख्यास्त निश्चीतपणान अविश्वास्यांक पावटली.", "विटरांत-हनाफींची पद्दत.", "कुनूतांत उमर (र.) हाचे कडल्यान अहवाल मेळ्ळो."),
        "dua_sleep_aslamtu" to DuaText("न्हिदचे पयलीं निमाणें उतर", "हे अल्लाह, हांव स्वताक तुज्याकडेन समर्पण करता, म्हजें प्रकरण तुज्या हातांत सोपयता आनी तुज्या सुरक्षेक म्हजी फाट समर्पण करता, तुज्या आसेक लागून आनी तुज्या भंयाक लागून. तुज्या शिवाय कोणूच आलाशिरो ना आनी तुका सोडपाक कोणूच ना. तुज्या पुस्तकांत आनी तुज्या पैगंबराक धाडून हांचो विश्वास आसा.", "वूडू उपरांत उजवे वटेन न्हिदप-न्हिदचे पयलींचे निमाणें उतर.", "त्या रातीक ताका मरण आयल्यार, तो फित्राह (इस्लाम) दिसा मरता."),
        "dua_waking_night" to DuaText("रातचें उठप", "अल्लाह सोडून कोणाकूय पुजा करपाचो अधिकार ना, एकलो, भागीदार नासतना. ताचेंच राज्य आनी ताचीच तोखणाय, आनी तो सगळ्या गजालींचेर अधिकार दवरता. सगळ्यो तोखणाय अल्लाहाक आसा, अल्लाह हो व्हडलो, अल्लाह सोडून कोणाकूय तोखणाय करपाचो अधिकार ना, अल्लाह सगळ्यांत व्हडलो, आनी अल्लाह सोडून कोणाकूच बळ वा शक्ती ना. हे अल्लाह, म्हाका माफ कर.", "रातचें उठतकच.", "ताच्या दुआक जाप मेळटा, आनी तो वुडू करून प्रार्थना केल्यार ताची प्रार्थना मान्य जाता."),
        "dua_hamm_ibn_masud" to DuaText("दुखा खातीर दुआ (इब्न मसूद)", "हे अल्लाह, हांव तुजो सेवक, तुज्या सेवकाचो पूत, तुज्या दासीचो पूत. म्हजो अग्रबंद तुज्या हातांत आसा, तुजो म्हजेचेर आज्ञा पाळला, आनी म्हज्या विशीं तुजो हुकूम न्याय्य आसा. तूं आपलें नांव घेतिल्लो, वा तुज्या पुस्तकांत प्रकट जाल्लो, वा तुज्या खंयच्याय सृष्टीक शिकयल्लो, वा नदरेंतल्या गिन्यानांत तुज्या कडेन दवरिल्लो दरेक नांवान हांव तुका विचारता-तूं कुराणाक म्हज्या काळजाचो झरो, म्हज्या हड्ड्याचो उजवाड, म्हजें दुख्ख पयस करप आनी म्हजी चिंता पयस करप.", "दुख्ख आनी त्रासांत-अल्लाह दुख्खाक आनंदान बदलटा.", "अल्लाह ताची चिंता आनी दुख्ख पयस करता आनी ताका ताचे सुवातेर खोस दिता."),
        "dua_difficulty_sahl" to DuaText("जेन्ना कितेंय कठीण आसता", "हे अल्लाह, तूं कितें सोंपें करता ताचे भायर कांयच सोंपें ना, आनी तुजी इत्सा आसल्यार कठीण सोंपे करता.", "जेन्ना कितेंय कठीण दिसता.", "परिक्षा आनी कठीण कामां करप सोंपें."),
        "dua_musibah" to DuaText("अपान अ कॅलॅमिटी (इस्तिरजा)", "आमी अल्लाहचे आसात आनी ताचे कडेन परत येतले. हे अल्लाह, म्हज्या दुख्खीपणांत म्हाका फळ दिवचें आनी ताचे बदला म्हजे खातीर कितें तरी बरें करचें.", "खंयच्याय लुकसाण वा संकटाचेर.", "अल्लाह निश्चीतच कितें तरी बरें दिता-उम्म सलाम (रा) पैगंबर सल्ल्याह अल्लीह् ओस्लम हाका दिलो."),
        "dua_debt" to DuaText("रिणांतल्यान मेकळीक मेळोवपा खातीर", "हे अल्लाह, तूं बेकायदेशीर केल्या त्या आड तूं जे कायदेशीर केलां तें म्हाका फावोशें कर, आनी तुज्या अनुदाना वरवीं म्हाका तुज्या भायर सगळ्या पसून स्वतंत्र कर.", "रीण फारीक करपा खातीर-अली (आर. ए.) हाणें शिकयिल्लें.", "जरी रिण दोंगरा सारकें आसलें तरी अल्लाह तें सोंपयलो."),
        "dua_anger" to DuaText("राग येता तेन्ना", "शापित शयताना कडल्यान हांव अल्लाहाक आलाशिरो मागता.", "राग येता तेन्ना.", "पैगंबर सल्ल्याह अलियाह वसलमान सांगलेंः जर तो अशें म्हणटलो जाल्यार ताचो राग पयस जातलो."),
        "dua_waswasa" to DuaText("विश्वासांत वासवासा आड", "म्हाका अल्लाह आनी ताच्या दूतांचेर विस्वास आसा.", "जेन्ना सैतान श्रद्धे विशीं कुजबुज करता तेन्ना येता.", "जेन्ना कुजबुज येता तेन्ना हें सांग आनी थंयच थांबो (आनी अल्लाहांत आलाशिरो घेयात)."),
    )
}
